import { useState } from 'react';
import styles from './TransactionForm.module.css';

const TransactionForm = ({ onAddTransaction, currentBalance = 0, setCurrentBalance = () => {} }) => {
  const [formData, setFormData] = useState({
    description: '',
    amount: '',
    type: 'income',
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    // Validación del monto
    const amount = parseFloat(formData.amount);
    if (isNaN(amount) || amount <= 0) {
      alert('Por favor ingrese un monto válido mayor a cero');
      return;
    }

    // Preparar datos de fecha/hora
    const now = new Date();
    const transaction = {
      ...formData,
      amount: amount,
      day: now.toLocaleDateString('es-ES', { weekday: 'long' }),
      time: now.toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' }),
      date: now.toISOString().split('T')[0]
    };

    // Actualizar saldo
    const amountToUpdate = transaction.type === 'income' ? amount : -amount;
    const newBalance = currentBalance + amountToUpdate;
    
    // Validar saldo negativo (opcional)
    if (newBalance < 0) {
      alert('Saldo insuficiente para realizar esta transacción');
      return;
    }

    setCurrentBalance(newBalance);
    onAddTransaction(transaction);
    
    // Resetear formulario
    setFormData({
      description: '',
      amount: '',
      type: 'income',
    });
  };

  return (
    <form className={styles.form} onSubmit={handleSubmit}>
      <div className={styles.balanceDisplay}>
        Saldo Actual: ${currentBalance.toFixed(2)}
      </div>
      
      <input
        type="text"
        name="description"
        placeholder="Descripción"
        value={formData.description}
        onChange={handleChange}
        
      />
      <input
        type="number"
        name="amount"
        placeholder="Monto"
        value={formData.amount}
        onChange={handleChange}
        min="0.01"
        step="0.01"
        required
      />
      <select name="type" value={formData.type} onChange={handleChange}>
        <option value="income">Ingreso</option>
        <option value="expense">Gasto</option>
      </select>
      <button type="submit">
        {formData.type === 'income' ? 'Agregar Ingreso' : 'Agregar Gasto'}
      </button>
    </form>
  );
};

// Valores por defecto para las props
TransactionForm.defaultProps = {
  currentBalance: 0,
  setCurrentBalance: () => {}
};

export default TransactionForm;
